const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[character]);
const dayKey = (value = new Date()) => new Intl.DateTimeFormat('en-CA',{ timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit' }).format(new Date(value));
