    return {minimumRestHours:11,maxConsecutiveDays:6,maxWeeklyHours:48,dayOffPolicy:'schedule_rules_v1',patternId,rotationMode:'balanced_cycle',rotationBlockDays:2,rotationSet:'auto',scheduleRows:rosterWeekdays.map(([dayOfWeek])=>({dayOfWeek,dayOffAllowed:allowed.includes(dayOfWeek),shifts:shiftsFor(dayOfWeek)}))};
